import {TODAY,EFFECTIVE,TENANT,PLANS,plan,money,date,freshState,event,employeeRecord,validateBeneficiaries,submitDeclaration,confirm,requestChange,confirmChange,coverage,payrollRows,makeExport} from './core.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], KEY='ibcp-auto-demo-v1';
const esc=v=>String(v??'').replace(/[&<>\x22']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\x22':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.schema!==1||!Array.isArray(state.records))state=freshState();}catch{state=freshState();}
let role='employee',page=employeeRecord(state)?'program':'join',period=EFFECTIVE,filter='all',query='',tablePage=0,verification=false,familyId=null;
const I={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',doc:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',arrow:'M5 12h14 M13 6l6 6-6 6',left:'M19 12H5 M11 6l-6 6 6 6',check:'M5 12l4 4L19 6',plus:'M12 5v14 M5 12h14',x:'M6 6l12 12 M18 6L6 18',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',download:'M12 3v12 M7 10l5 5 5-5 M5 17v4h14v-4',upload:'M12 16V4 M7 9l5-5 5 5 M5 17v4h14v-4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',mail:'M3 5h18v14H3z M3 5l9 8 9-8',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7v1',chart:'M3 3v18h18 M7 16V9 M12 16V5 M17 16v-5',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M16 3v4 M8 3v4 M4 11h16',wallet:'M20 8V5H4v15h16V8H3 M16 12h5v5h-5z',help:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M9 8a3 3 0 0 1 6 0c0 2-3 3-3 5 M12 17v1',menu:'M4 6h16 M4 12h16 M4 18h16',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-1l2 6 M4 12l2 6a7 7 0 0 0 12-1',settings:'M4 7h16 M4 17h16 M9 4v6 M15 14v6',copy:'M9 8h12v13H9z M5 16H3V3h12v2'};
const icon=(n,cl='')=>`<svg class='${cl}' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'><path d='${I[n]||I.doc}'/></svg>`;
const btn=(label,action,cls='',ico='')=>`<button class='btn ${cls}' type='button' data-action='${action}'>${ico?icon(ico):''}${label}</button>`;
const badge=(text,color='')=>`<span class='badge ${color}'><span class='dot'></span>${text}</span>`;
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Przeglądarka nie zapisuje postępu. Demo działa w tej sesji.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function error(t){const e=$('#form-error')||$('#modal-error');if(e){e.textContent=t;e.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(t);}
function modal(title,content){$('#modal').innerHTML=`<div class='modal-content'><div class='modal-top'><h2>${title}</h2><button class='close' data-action='close' aria-label='Zamknij'>${icon('x')}</button></div>${content}<div id='modal-error' class='error' role='alert'></div></div>`;$('#modal').showModal();}
function close(){if($('#modal').open)$('#modal').close();}
function navItem(key,label,ico,count=''){return `<button data-page='${key}' class='${page===key?'active':''}' ${page===key?`aria-current='page'`:''}>${icon(ico)}${label}${count?`<span class='nav-count'>${count}</span>`:''}</button>`;}
function render(){
 const me=employeeRecord(state),pending=state.records.filter(r=>r.tenant===TENANT&&r.status==='pending').length;
 $('#app').innerHTML=`<div class='shell'><aside class='sidebar'><a href='#' class='bcp-brand' data-page='${me?'program':'join'}' aria-label='BCP Polska — strona główna iBCP'><img src='./assets/brand/BCP_Polska_logo_broker.svg' alt='BCP Polska' width='164' height='65'></a><div class='product-heading'><strong>iBCP</strong><span>Życie i zdrowie</span></div><div class='company-card'><div class='auto-mark'>A↗</div><div><strong>Auto Demo sp. z o.o.</strong><small>Program pracowniczy</small></div></div><div class='nav-label'>${role==='hr'?'STREFA KADR':'TWOJE UBEZPIECZENIE'}</div><nav class='nav' aria-label='Nawigacja główna'>${role==='hr'?navItem('overview','Przegląd','grid')+navItem('applications','Zgłoszenia','doc',pending)+navItem('exports','Eksporty','download')+navItem('history','Historia operacji','clock'):navItem('join',me?'Przystąpienie':'Dołącz do programu','home')+navItem('program','Mój program','shield')+navItem('family','Moja rodzina','users')+navItem('documents','Dokumenty','doc')+navItem('history','Historia zmian','clock')}</nav><div class='sidebar-bottom'><div class='help-card'><strong>${icon('help')} Pomoc w programie</strong><p>Wszystkie ważne informacje w jednym miejscu.</p><button class='text-button mt16' data-action='help'>Zobacz pomoc ${icon('arrow')}</button></div><nav class='nav'><a href='./architecture.html' target='_blank' rel='noopener'>${icon('settings')}Projekt i architektura ${icon('arrow')}</a></nav><div class='sidebar-footer mt16'>iBCP · platforma BCP Polska</div></div></aside><div class='workspace'><div class='mobile-brand'><img src='./assets/brand/BCP_Polska_logo_broker.svg' alt='BCP Polska' width='164' height='65'><div class='mobile-product'><strong>iBCP</strong><small>Życie i zdrowie</small></div></div><header class='topbar'><button class='menu-button' data-action='menu' aria-label='Otwórz nawigację'>${icon('menu')}Menu</button><div class='breadcrumb'>${icon('home')}<span>/</span>Auto Demo<span>/</span><strong>${role==='hr'?'Panel kadr':'Strefa pracownika'}</strong></div><div class='top-actions'><div class='switcher' aria-label='Widok demonstratora'><button data-role='employee' class='${role==='employee'?'active':''}'>Pracownik</button><button data-role='hr' class='${role==='hr'?'active':''}'>Kadry</button></div><div class='avatar' title='Konto demonstracyjne'>${role==='hr'?'KD':state.profile?esc(initials(state.profile.name)):'AD'}</div></div></header><div class='demo-bar'><span><strong>WERSJA DEMO</strong>Wyłącznie fikcyjne dane. Logowanie, TU i zaproszenia są symulowane.</span><button data-action='reset'>Reset demo</button></div><main id='main' class='main' tabindex='-1'>${role==='hr'?hrView():employeeView()}<footer class='footer-line'><div class='footer-brand'><img src='./assets/brand/BCP_Polska_logo.svg' alt='BCP Polska — WORTH MORE' width='164' height='69'><div class='footer-meta'><span>© 2026 BCP Polska · Auto Demo sp. z o.o.</span><a href='./architecture.html' target='_blank' rel='noopener'>Technologia, model danych i pytania przed pilotem ↗</a></div></div></footer></main></div></div>`;
 bindForms();
}
function heading(eyebrow,title,desc,extra=''){return `<div class='heading'><div>${eyebrow?`<div class='eyebrow'>${eyebrow}</div>`:''}<h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${extra}</div>`;}
function employeeView(){if(familyId)return familyActivation();if(page==='join')return state.step===0?welcome():flow();if(page==='program')return program();if(page==='family')return family();if(page==='documents')return documents();return history();}
function welcome(){return `${heading('TWÓJ PROGRAM PRACOWNICZY','Dobrze mieć spokojną głowę.','Ubezpieczenie dla Ciebie i Twoich bliskich. Wszystko załatwisz tutaj.',badge('Program otwarty','green'))}<div class='intro-grid'><section class='card welcome-card'><div class='hero-shield'>${icon('shield')}</div><h2>Wybierz ochronę,<br>która pasuje do Ciebie.</h2><p class='subtext'>Poznaj warianty, sprawdź miesięczny koszt i dołącz do programu Auto Demo. Bez drukowania dokumentów.</p><div class='welcome-line'></div><div class='feature-row'><div>${icon('doc')}Deklaracja online</div><div>${icon('users')}Możliwość dołączenia rodziny</div></div></section><form id='code-form' class='card code-form'><h2>Zacznij od kodu firmy</h2><p class='subtext'>Kod pozwala odnaleźć program Twojego pracodawcy.</p><div class='form-field mt24'><label for='company-code'>Kod firmy</label><input id='company-code' class='code-input' name='code' value='AUTO200' autocomplete='off' required><span class='input-help'>Kod demonstracyjny: <strong>AUTO200</strong></span></div><div id='form-error' class='error' role='alert'></div><button class='btn primary wide mt16' type='submit'>Przejdź do programu ${icon('arrow')}</button><p class='tiny mt16'>200 pracowników · Auto Demo sp. z o.o.<br>Wybór wariantu nie zobowiązuje do przystąpienia.</p></form></div><div class='section-title'><h2>Trzy warianty. Twój wybór.</h2><span class='tiny'>Składka miesięczna za osobę</span></div>${plans(false)}<div class='bottom-note'>${icon('info')}<span>Program demonstracyjny z oznaczeniem PZU Życie. Kwoty świadczeń są fikcyjne i nie stanowią oferty ani potwierdzonych warunków PZU.</span></div>`;}
function plans(selectable){return `<div class='plans'>${PLANS.map(p=>`<article class='card plan ${selectable?'selectable':''} ${selectable&&state.selectedPlan===p.id?'selected':''}'><div class='plan-tag'>${p.tag}</div><div class='flex between'><h3 class='plan-title'>${p.name}</h3>${selectable?`<span class='selected-mark'>${state.selectedPlan===p.id?icon('check'):''}</span>`:''}</div><div class='plan-price'>${p.price} zł <span>/ miesiąc</span></div><p class='plan-desc'>${p.desc}</p><ul><li>${icon('check')}<span>Życie<strong>${money(p.life)}</strong></span></li><li>${icon('check')}<span>Poważne zachorowanie<strong>${money(p.illness)}</strong></span></li><li>${icon('check')}<span>Pobyt w szpitalu<strong>${p.hospital} zł / dzień</strong></span></li></ul>${selectable?`<button class='btn ${state.selectedPlan===p.id?'dark':''}' data-plan='${p.id}' aria-pressed='${state.selectedPlan===p.id}'>${state.selectedPlan===p.id?'Wybrany wariant':'Wybieram ten wariant'}</button>`:''}</article>`).join('')}</div>`;}
function steps(){const labels=['Program','Konto','Wariant','Deklaracja','Gotowe'];return `<ol class='steps' aria-label='Etapy przystąpienia'>${labels.map((l,i)=>`<li class='${state.step===i+1?'current':state.step>i+1?'complete':''}' ${state.step===i+1?`aria-current='step'`:''}><span class='step-num'>${state.step>i+1?icon('check'):i+1}</span>${l}</li>`).join('')}</ol>`;}
function summary(){const p=plan(state.selectedPlan);return `<aside class='card summary-card'><div class='summary-brand'><span class='insurer-mark'>PZU</span><div><h3 style='font-size:12px'>PZU Życie</h3><p class='tiny'>Oznaczenie programu demo</p></div></div><p class='tiny'>WYBRANY WARIANT</p><h3 class='mt16' style='margin-top:5px'>${p.name}</h3><div class='price mt16'>${money(p.price)}</div><p class='tiny'>miesięcznie za jedną osobę</p><div class='divider'></div><div class='detail-list'><div class='detail-item'><span>Płatność</span><strong>Z wynagrodzenia</strong></div><div class='detail-item'><span>Planowany początek</span><strong>1 grudnia 2026</strong></div><div class='detail-item'><span>Pracodawca</span><strong>Auto Demo</strong></div></div><div class='notice mt24'>${icon('info')}<span>Ochrona wymaga przyjęcia przez TU. Daty i świadczenia w tym programie są demonstracyjne.</span></div></aside>`;}
function flow(){const me=employeeRecord(state);if(me&&state.step===5)return confirmation(me);const title=state.step===1?'Twój program jest gotowy.':state.step===2?verification?'Potwierdź konto demo.':'Utwórz swoje konto.':state.step===3?'Wybierz swój wariant.':'Sprawdź i złóż deklarację.';return `${heading('DOŁĄCZ DO PROGRAMU',title,state.step===3?'Porównaj miesięczny koszt i przykładowe świadczenia.':'Auto Demo sp. z o.o. · Program demonstracyjny')}${steps()}${state.step===3?`${plans(true)}<div class='notice mt16'>${icon('info')}<span>Wszystkie zakresy i kwoty świadczeń są fikcyjne. Nie są ofertą PZU. Pełne warunki muszą zostać dostarczone i zaakceptowane dla konkretnego programu.</span></div><div class='form-actions'>${btn('Wstecz','step-2','ghost','left')}<div class='flex'><span class='subtext'>${plan(state.selectedPlan).name} · <strong>${money(plan(state.selectedPlan).price)}/mies.</strong></span>${btn('Przejdź do deklaracji','step-4','primary','arrow')}</div></div>`:`<div class='flow-layout'><section class='card card-pad'>${state.step===1?programFound():state.step===2?verification?verificationForm():registration():declaration()}</section>${summary()}</div>`}`;}
function programFound(){return `<div class='success-icon'>${icon('check')}</div><h2>Witaj w Auto Demo</h2><p class='subtext mt16'>Kod firmy został rozpoznany. Możesz teraz utworzyć konto i wybrać wariant.</p><div class='divider'></div><div class='detail-list'><div class='detail-item'><span>Program</span><strong>Życie i zdrowie · Auto Demo 2026</strong></div><div class='detail-item'><span>Ubezpieczyciel w demo</span><strong>PZU Życie</strong></div><div class='detail-item'><span>Dostępne warianty</span><strong>60 zł · 90 zł · 120 zł</strong></div><div class='detail-item'><span>Sposób płatności</span><strong>Potrącenie z wynagrodzenia</strong></div></div><div class='notice mt24'>${icon('lock')}<span>W tej wersji korzystasz tylko z danych fikcyjnych. Przystąpienie nie uruchamia rzeczywistej ochrony.</span></div><div class='form-actions'>${btn('Zmień kod','step-0','ghost','left')}${btn('Utwórz konto demo','step-2','primary','arrow')}</div>`;}
function registration(){const n=(state.profile?.name||'Alex Demo').split(' ');return `<h2>Twoje dane</h2><p class='subtext mt16'>Użyj prywatnego adresu demonstracyjnego w domenie example.com.</p><form id='register-form' class='mt24'><div class='form-grid'><div class='form-field'><label for='first'>Imię</label><input id='first' name='first' value='${esc(n[0])}' required maxlength='40' autocomplete='off'></div><div class='form-field'><label for='last'>Nazwisko</label><input id='last' name='last' value='${esc(n.slice(1).join(' '))}' required maxlength='60' autocomplete='off'></div><div class='form-field full'><label for='email'>Prywatny e-mail demo</label><input id='email' name='email' type='email' value='${esc(state.profile?.email||'alex.demo@example.com')}' required autocomplete='off'><span class='input-help'>Przykład: alex.demo@example.com. Wiadomości nie są wysyłane.</span></div><div class='form-field full'><label for='password'>Hasło demonstracyjne</label><input id='password' name='password' type='password' value='Demo-iBCP-2026!' minlength='10' required autocomplete='new-password'><span class='input-help'>Zostaw przykładowe hasło. Nie używaj własnego — to symulacja konta.</span></div></div><div class='notice mt24'>${icon('lock')}<span>Hasło nie jest zapisywane. Następny krok pokazuje weryfikację drugim składnikiem w trybie demo.</span></div><div id='form-error' class='error' role='alert'></div><div class='form-actions'>${btn('Wstecz','step-1','ghost','left')}<button type='submit' class='btn primary'>Dalej ${icon('arrow')}</button></div></form>`;}
function verificationForm(){return `<div class='success-icon' style='background:var(--pale);color:var(--blue)'>${icon('lock')}</div><h2>Weryfikacja drugim składnikiem</h2><p class='subtext mt16'>Wpisz kod demonstracyjny. Ten ekran symuluje 2FA i nie uwierzytelnia rzeczywistego użytkownika.</p><form id='verify-form' class='mt24'><div class='form-field'><label for='otp'>Kod z aplikacji uwierzytelniającej — symulacja</label><input id='otp' class='code-display' name='otp' inputmode='numeric' pattern='[0-9]{6}' maxlength='6' required autocomplete='off' placeholder='000000'><span class='input-help'>Kod w tym demo: <strong>246810</strong></span></div><div id='form-error' class='error' role='alert'></div><div class='form-actions'>${btn('Wróć do danych','register-back','ghost','left')}<button class='btn primary' type='submit'>Potwierdź i wybierz wariant ${icon('arrow')}</button></div></form>`;}
function declaration(){return `<h2>Deklaracja przystąpienia</h2><p class='subtext mt16'>Sprawdź dane, wskaż uposażonych i potwierdź oświadczenia demonstracyjne.</p><form id='declaration-form'><div class='form-grid mt24'><div class='form-field'><label>Ubezpieczony</label><input readonly aria-label='Ubezpieczony' value='${esc(state.profile?.name)}'></div><div class='form-field'><label>Identyfikator demo zamiast PESEL</label><input readonly aria-label='Identyfikator demo zamiast PESEL' value='DEMO-0001'></div></div><div class='divider'></div><div class='flex between'><div><h3>Osoby uposażone</h3><p class='tiny mt16' style='margin-top:4px'>Łączna suma udziałów musi wynosić 100%.</p></div><button class='text-button' type='button' data-action='beneficiary-add'>${icon('plus')}Dodaj osobę</button></div>${state.beneficiaries.map((b,i)=>`<div class='beneficiary'><div class='form-field'><label for='ben-${i}'>Imię i nazwisko demo</label><input id='ben-${i}' name='ben-${i}' data-beneficiary='${i}' value='${esc(b.name)}' required maxlength='100' autocomplete='off'></div><div class='form-field'><label for='share-${i}'>Udział %</label><input id='share-${i}' name='share-${i}' type='number' min='1' max='100' value='${b.share}' required></div><button type='button' class='btn ghost' data-remove-beneficiary='${i}' aria-label='Usuń uposażonego ${i+1}'>${icon('x')}</button></div>`).join('')}<div class='divider'></div><h3>Dokumenty i oświadczenia</h3><div class='flex wrap gap8 mt16'>${btn('Makieta OWU','doc-owu','sm','doc')}${btn('Makieta karty produktu','doc-product','sm','doc')}${btn('Informacja o brokerze','doc-broker','sm','doc')}</div><label class='check-row'><input type='checkbox' name='documents' ${state.consents.documents?'checked':''} required><span>Zapoznałem(-am) się z dokumentami demonstracyjnymi. W produkcji w tym miejscu będą właściwe dokumenty i oświadczenia danego TU.</span></label><label class='check-row'><input type='checkbox' name='payroll' ${state.consents.payroll?'checked':''} required><span>Potwierdzam w demo potrącenie <strong>${money(plan(state.selectedPlan).price)} miesięcznie</strong> z wynagrodzenia. Docelowa treść zgody wymaga uzgodnienia.</span></label><label class='check-row'><input type='checkbox' name='statement' ${state.consents.statement?'checked':''} required><span>Potwierdzam, że używam fikcyjnych danych i składam wyłącznie deklarację testową.</span></label><div class='notice amber mt16'>${icon('clock')}<span>Planowany początek: <strong>1 grudnia 2026 r.</strong> Złożenie deklaracji nie oznacza objęcia ochroną. W demo decyzję TU zasymulujesz z panelu kadr.</span></div><div id='form-error' class='error' role='alert'></div><div class='form-actions'>${btn('Zmień wariant','step-3','ghost','left')}<button class='btn primary' type='submit'>Złóż deklarację demo ${icon('arrow')}</button></div></form>`;}
function confirmation(r){return `${heading('DEKLARACJA ZŁOŻONA','Pierwszy krok za Tobą.','Postęp przystąpienia sprawdzisz w zakładce „Mój program”.')}${steps()}<div class='flow-layout'><section class='card card-pad'><div class='success-icon'>${icon('check')}</div><h2 class='success-heading'>Dziękujemy, ${esc(state.profile.name.split(' ')[0])}.</h2><p class='subtext'>Twoja deklaracja <strong>${r.id}</strong> jest zapisana w tym demonstratorze.</p>${statusTimeline(r)}<div class='family-callout'><div><h3>Zadbaj także o bliskich</h3><p>Zaproś małżonka, partnera lub pełnoletnie dziecko. Każda osoba składa własną deklarację.</p></div>${btn('Zaproś rodzinę','go-family','primary','users')}</div><div class='form-actions'>${btn('Zobacz deklarację','my-declaration','','doc')}${btn('Przejdź do mojego programu','go-program','ghost','arrow')}</div></section>${summary()}</div>`;}
function statusTimeline(r){return `<div class='timeline'><div class='timeline-item'><div class='point'>${icon('check')}</div><div><strong>Deklaracja zapisana</strong><p>${date(r.created)} · ${r.id}</p></div></div><div class='timeline-item ${r.status==='pending'?'pending':''}'><div class='point'>${icon(r.status==='pending'?'clock':r.status==='rejected'?'x':'check')}</div><div><strong>${r.status==='pending'?'Oczekuje na potwierdzenie TU':r.status==='accepted'?'Przyjęta przez TU — symulacja':'Odrzucona przez TU — symulacja'}</strong><p>${r.status==='pending'?'W panelu kadr możesz zasymulować przyjęcie lub odrzucenie.':esc(r.confirmation?.reason||'Dane początkowe demonstratora')}</p></div></div><div class='timeline-item pending'><div class='point'>${icon('calendar')}</div><div><strong>${r.status==='accepted'?'Początek według potwierdzenia demo':'Wnioskowany początek ochrony'}</strong><p>${date(r.effective)} · wyłącznie scenariusz demonstracyjny</p></div></div></div>`;}
function empty(title,desc,action=''){return `<div class='card empty'>${icon('shield')}<h3>${title}</h3><p class='subtext'>${desc}</p>${action?`<div class='mt24'>${btn('Dołącz do programu','go-join','primary','arrow')}</div>`:''}</div>`;}
function program(){const r=employeeRecord(state);if(!r)return `${heading('TWÓJ PROGRAM','Ochrona w jednym miejscu.','Tu zobaczysz status deklaracji i historię swojego programu.')}${empty('Nie masz jeszcze deklaracji','Przejdź przez krótką ścieżkę przystąpienia.','join')}`;const p=plan(r.planId),pending=state.changes.filter(c=>c.recordId===r.id);return `${heading('MÓJ PROGRAM','Cześć, '+esc(state.profile.name.split(' ')[0])+'.','Twój program ubezpieczenia grupowego w Auto Demo.',statusBadge(r))}<div class='app-banner'><div><div class='eyebrow' style='color:#9bbfe8;margin-bottom:6px'>ŻYCIE I ZDROWIE · PZU ŻYCIE · DEMO</div><h2>Wariant ${p.name.toLowerCase()}</h2><p>${money(p.price)} / miesiąc · potrącenie z wynagrodzenia</p></div>${badge('Deklaracja '+r.id)}</div><div class='flow-layout'><div class='stack'><section class='card card-pad'><h2>Status przystąpienia</h2>${statusTimeline(r)}<div class='flex wrap gap8'>${btn('Moja deklaracja','my-declaration','','doc')}${btn('Zmień wariant','change','', 'refresh')}${btn('Zrezygnuj','cancel','ghost')}</div></section>${pending.length?`<section class='card card-pad'><h3>Twoje zmiany</h3>${pending.map(c=>`<div class='doc-row'>${icon('refresh')}<div><h3>${c.type==='cancel'?'Rezygnacja':'Zmiana na wariant '+plan(c.planId).name}</h3><p>Od ${date(c.effective)} · ${c.id}</p></div>${badge(c.status==='pending'?'Oczekuje na TU':'Przyjęta · demo',c.status==='pending'?'amber':'green')}</div>`).join('')}</section>`:''}<div class='family-callout'><div><h3>Bliscy też mogą dołączyć</h3><p>Własna deklaracja, wspólny płatnik.</p></div>${btn('Moja rodzina','go-family','','users')}</div></div>${summary()}</div>`;}
function family(){const me=employeeRecord(state);if(!me)return `${heading('MOJA RODZINA','Razem spokojniej.','Zaproś bliskich do programu Auto Demo.')}${empty('Najpierw złóż swoją deklarację','Po przystąpieniu możesz przygotować zaproszenie dla bliskiej osoby.','join')}`;return `${heading('MOJA RODZINA','Zadbaj o swoich bliskich.','Każda zaproszona osoba wybiera wariant i składa własną deklarację.',btn('Zaproś osobę','invite','primary','plus'))}<div class='notice mb16'>${icon('wallet')}<span>W tym scenariuszu demo jesteś płatnikiem składki za siebie i rodzinę. Samo zaproszenie nie zwiększa potrącenia. Kwota zmienia się po przyjęciu deklaracji przez TU i od właściwej daty.</span></div><section class='card card-pad'><h2>Twoja rodzina w programie</h2>${state.invites.length?state.invites.map(i=>{const r=state.records.find(r=>r.personId===i.id);return `<div class='doc-row'><div class='avatar'>${esc(initials(i.name))}</div><div><h3>${esc(i.name)}</h3><p>${esc(i.relation)} · ${esc(i.email)}</p></div><div style='margin-left:auto;text-align:right'>${r?statusBadge(r):badge('Link demo gotowy','blue')}<div class='mt16' style='margin-top:6px'>${r?`<span class='tiny'>${plan(r.planId).name} · ${money(plan(r.planId).price)}/mies.</span>`:`<button class='text-button' data-family='${i.id}'>Otwórz ścieżkę bliskiej osoby ${icon('arrow')}</button>`}</div></div></div>`}).join(''):`<div class='empty' style='padding-bottom:20px'>${icon('users')}<h3>Jeszcze nikogo nie zaproszono</h3><p class='subtext'>Możesz zaprosić małżonka, partnera lub pełnoletnie dziecko.</p><div class='mt24'>${btn('Przygotuj zaproszenie','invite','primary','mail')}</div></div>`}</section><div class='card card-pad mt24'><div class='flex between'><div><h3>Łączna składka płatnika</h3><p class='subtext mt16' style='margin-top:5px'>Przyjęte deklaracje skuteczne na 1 grudnia 2026</p></div><strong style='font-size:27px;color:var(--navy)'>${money(payrollRows(state,EFFECTIVE).find(p=>p.employeeId===me.employeeId)?.total||0)}</strong></div></div>`;}
function inviteModal(){modal('Zaproś bliską osobę',`<p class='subtext mb16'>Przygotujemy link demonstracyjny. Żaden e-mail nie zostanie wysłany.</p><form id='invite-form'><div class='form-grid'><div class='form-field'><label for='relative-name'>Imię i nazwisko demo</label><input id='relative-name' name='name' value='Marta Demo' required maxlength='100'></div><div class='form-field'><label for='relation'>Relacja</label><select id='relation' name='relation'><option>Małżonek / małżonka</option><option>Partner / partnerka</option><option>Pełnoletnie dziecko</option></select></div><div class='form-field full'><label for='relative-email'>E-mail demo</label><input id='relative-email' name='email' type='email' value='marta.demo@example.com' required><span class='input-help'>Dozwolone są adresy w domenie example.com.</span></div></div><div class='notice mt24'>${icon('users')}<span>Bliska osoba wypełnia własną deklarację. Płatnik: ${esc(state.profile.name)}.</span></div><div class='form-actions'>${btn('Anuluj','close','ghost')}<button type='submit' class='btn primary'>Przygotuj link ${icon('arrow')}</button></div></form>`);bindForms();}
function familyActivation(){const inv=state.invites.find(i=>i.id===familyId);if(!inv){familyId=null;return family();}if(inv.status==='joined')return `${heading('KONTO CZŁONKA RODZINY','Deklaracja rodziny zapisana.','Konto i deklaracja bliskiej osoby są niezależne od konta pracownika.')}${empty('Oczekuje na potwierdzenie TU','Pracownik pozostaje płatnikiem składki.')}<div class='mt24'>${btn('Wróć do konta pracownika','family-return','primary','left')}</div>`;return `${heading('ZAPROSZENIE DO PROGRAMU','Witaj, '+esc(inv.name.split(' ')[0])+'.','Symulacja osobnego konta członka rodziny · Auto Demo') }<div class='flow-layout'><section class='card card-pad'><h2>Dołącz na własnym koncie</h2><p class='subtext mt16'>${esc(state.profile.name)} zaprasza Cię do programu i będzie opłacać Twoją składkę.</p><form id='family-join-form' class='mt24'><div class='form-grid'><div class='form-field'><label>Twoje imię i nazwisko demo</label><input readonly aria-label='Imię i nazwisko członka rodziny' value='${esc(inv.name)}'></div><div class='form-field'><label>Twój e-mail demo</label><input readonly aria-label='E-mail członka rodziny' value='${esc(inv.email)}'></div><div class='form-field full'><label for='family-plan'>Wybierz wariant dla siebie</label><select id='family-plan' name='plan'>${PLANS.map(p=>`<option value='${p.id}' ${p.id==='plus'?'selected':''}>${p.name} — ${money(p.price)} / miesiąc</option>`).join('')}</select></div><div class='form-field full'><label for='family-otp'>Kod weryfikacyjny konta — symulacja</label><input id='family-otp' name='otp' inputmode='numeric' maxlength='6' required placeholder='246810'><span class='input-help'>Kod demo: 246810. E-mail i 2FA są symulowane.</span></div></div><label class='check-row mt16'><input name='adult' type='checkbox' required><span>Potwierdzam pełnoletność i fikcyjność danych w tym scenariuszu.</span></label><label class='check-row'><input name='docs' type='checkbox' required><span>Zapoznałem(-am) się z <button class='text-button' type='button' data-action='doc-product'>dokumentem demonstracyjnym</button> i składam własną deklarację testową.</span></label><div id='form-error' class='error' role='alert'></div><div class='form-actions'>${btn('Wróć do pracownika','family-return','ghost','left')}<button class='btn primary' type='submit'>Złóż deklarację rodziny ${icon('arrow')}</button></div></form></section><aside class='card summary-card'><h3>Twój płatnik</h3><p class='subtext mt16'>${esc(state.profile.name)}</p><div class='divider'></div><div class='detail-list'><div class='detail-item'><span>Pracodawca</span><strong>Auto Demo</strong></div><div class='detail-item'><span>Tryb płatności</span><strong>Potrącenie z wynagrodzenia płatnika</strong></div></div><div class='notice mt24'>${icon('info')}<span>Zakres, kwoty i zasady dotyczą tylko tego demo. Nie są potwierdzonymi warunkami PZU.</span></div></aside></div>`;}
function documents(){return `${heading('DOKUMENTY','Wszystko pod ręką.','Dokumenty i informacje związane z Twoim programem.')}<div class='notice amber mb16'>${icon('info')}<span>Poniższe materiały są makietami. Nie zastępują OWU, karty produktu, informacji prawnych ani zatwierdzonej deklaracji TU.</span></div><section class='card card-pad'>${[['owu','Ogólne warunki ubezpieczenia','Makieta dokumentu · wymagany oryginał TU'],['product','Karta produktu i porównanie wariantów','Przykładowe świadczenia · dane fikcyjne'],['broker','Informacja o brokerze i danych osobowych','Zakres informacji do uzupełnienia przed pilotem'],['continuation','Odejście z pracy i kontynuacja','Informacja demonstracyjna · warunki do ustalenia']].map(([id,title,desc])=>`<div class='doc-row'><div class='quick-icon'>${icon('doc')}</div><div><h3>${title}</h3><p>${desc}</p></div>${btn('Otwórz','doc-'+id,'sm','arrow')}</div>`).join('')}${employeeRecord(state)?`<div class='doc-row'><div class='quick-icon'>${icon('doc')}</div><div><h3>Twoja deklaracja demo</h3><p>${employeeRecord(state).id} · ${date(TODAY)}</p></div>${btn('Podgląd','my-declaration','sm','arrow')}</div>`:''}</section>`;}
function history(){const me=employeeRecord(state);const logs=role==='hr'?state.audit:state.audit.filter(l=>l.recordId===me?.id||state.changes.some(c=>c.id===l.recordId&&c.recordId===me?.id)||state.invites.some(i=>i.id===l.recordId));return `${heading('HISTORIA',role==='hr'?'Historia operacji.':'Twoje zmiany w programie.','Zapis operacji wykonanych w tym demonstratorze.')}<section class='card card-pad'>${logs.length?logs.map(l=>`<div class='audit-item'>${icon('clock')}<div><strong>${esc(l.type)}</strong><p>${esc(l.detail)} · ${esc(l.recordId)}</p></div><time>${new Date(l.at).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'})}</time></div>`).join(''):`<div class='empty'>${icon('clock')}<h3>Historia jest jeszcze pusta</h3><p class='subtext'>Złóż deklarację, przygotuj eksport lub zasymuluj odpowiedź TU.</p></div>`}</section><p class='tiny mt16'>Historia lokalna służy pokazaniu procesu. Produkcyjny dziennik audytowy wymaga niezależnego, chronionego zapisu po stronie serwera.</p>`;}
function statusBadge(r){if(r.status==='rejected')return badge('Odrzucona','red');if(r.status==='pending')return badge('Oczekuje na TU','amber');return r.effective>TODAY?badge('Przyjęta · od 1.12','blue'):badge('Aktywna','green');}
function periodSelect(){return `<select class='compact' id='period' aria-label='Okres rozliczeniowy'><option value='2026-11-01' ${period==='2026-11-01'?'selected':''}>Listopad 2026</option><option value='2026-12-01' ${period===EFFECTIVE?'selected':''}>Grudzień 2026</option></select>`;}
function hrView(){if(page==='history')return history();if(page==='exports')return exportsView();const records=state.records.filter(r=>r.tenant===TENANT),active=records.filter(r=>r.kind==='employee'&&coverage(state,r,period)).length,pending=records.filter(r=>r.status==='pending').length,families=records.filter(r=>r.kind==='family'&&coverage(state,r,period)).length,payroll=payrollRows(state,period),total=payroll.reduce((a,r)=>a+r.total,0),pct=(active/200*100);return `${heading('PANEL KADR · AUTO DEMO',page==='applications'?'Zgłoszenia pracowników.':'Twój program pod kontrolą.',page==='applications'?'Przystąpienia, zmiany i rezygnacje w jednym miejscu.':'Przystąpienia, partycypacja i rozliczenia — bez zbędnego szukania.',periodSelect())}${page==='overview'?`<div class='stats-grid'><div class='card stat'><div class='stat-top'>Pracownicy w ochronie ${icon('users')}</div><div class='stat-value'>${active}<span>/ 200</span></div><div class='stat-bottom'>Na pierwszy dzień wybranego miesiąca</div></div><div class='card stat'><div class='stat-top'>Partycypacja ${icon('chart')}</div><div class='stat-value'>${pct.toLocaleString('pl-PL')}<span>%</span></div><div class='progress-track'><div class='progress-fill' style='width:${pct}%'></div></div></div><div class='card stat'><div class='stat-top'>Oczekujące deklaracje ${icon('clock')}</div><div class='stat-value'>${pending}</div><div class='stat-bottom'>Wymagają potwierdzenia TU</div></div><div class='card stat'><div class='stat-top'>Składka miesięczna ${icon('wallet')}</div><div class='stat-value' style='font-size:26px'>${money(total)}</div><div class='stat-bottom'>Pracownicy i przyjęci członkowie rodzin</div></div></div><div class='hr-overview'><section class='card chart-card'><div class='flex between'><h3>Udział w programie</h3>${badge('200 pracowników')}</div><div class='chart-layout'><div class='donut' style='background:conic-gradient(var(--blue-700) 0deg ${pct*3.6}deg,var(--blue-100) ${pct*3.6}deg)'><div class='donut-center'><strong>${pct.toLocaleString('pl-PL')}%</strong><span>partycypacji</span></div></div><div class='legend'><div class='legend-row'><span class='legend-swatch'></span>Pracownicy w ochronie<strong>${active}</strong></div><div class='legend-row'><span class='legend-swatch' style='background:var(--blue-100)'></span>Pozostali pracownicy<strong>${200-active}</strong></div><div class='legend-row' style='padding-top:10px;border-top:1px solid var(--line)'>Rodzina poza mianownikiem<strong>${families}</strong></div></div></div></section><section class='card chart-card'><h3>Szybkie działania</h3><button class='quick-action' data-action='export-payroll'><span class='quick-icon'>${icon('download')}</span><span><strong>Pobierz listę płac</strong><small>CSV · kwoty pogrupowane według płatnika</small></span>${icon('chevron')}</button><button class='quick-action' data-action='export-tu'><span class='quick-icon'>${icon('upload')}</span><span><strong>Przygotuj eksport do TU</strong><small>Format demo · oczekujące deklaracje</small></span>${icon('chevron')}</button><button class='quick-action' data-action='mass-invite'><span class='quick-icon'>${icon('mail')}</span><span><strong>Zaproszenia pracowników</strong><small>Przygotuj wiadomość z kodem firmy</small></span>${icon('chevron')}</button></section></div>`:''}${changesTable()}${recordsTable()}<div class='bottom-note'>${icon('info')}<span>Podgląd kadr w demonstratorze zawiera dodatkowe przyciski symulacji TU. W produkcji potwierdzenia pochodzą z uzgodnionego kanału TU, a uprawnienia są egzekwowane po stronie serwera.</span></div>`;}
function changesTable(){const changes=state.changes.filter(c=>c.tenant===TENANT);return changes.length?`<section class='card card-pad mb16'><h3>Zmiany i rezygnacje</h3>${changes.map(c=>`<div class='doc-row'>${icon('refresh')}<div><h3>${esc(employeeRecord(state).name)} · ${c.type==='cancel'?'Rezygnacja':'Zmiana wariantu na '+plan(c.planId).name}</h3><p>${c.id} · skuteczność ${date(c.effective)}</p></div><div style='margin-left:auto'>${c.status==='pending'?`<button class='btn sm' data-confirm-change='${c.id}'>Potwierdź · symulacja</button>`:badge('Przyjęta · symulacja','green')}</div></div>`).join('')}</section>`:'';}
function filteredRecords(){return state.records.filter(r=>r.tenant===TENANT&&(filter==='all'||r.status===filter)&&(r.name+' '+r.employeeId+' '+r.id).toLocaleLowerCase('pl').includes(query.toLocaleLowerCase('pl'))).sort((a,b)=>a.status==='pending'&&b.status!=='pending'?-1:b.status==='pending'&&a.status!=='pending'?1:b.id.localeCompare(a.id));}
function recordsTable(){return `<section class='card table-card'><div class='table-head'><h2>Przystąpienia do programu <span class='badge' style='margin-left:7px'>${state.records.length}</span></h2><div class='table-tools'><div class='search'>${icon('search')}<input id='table-search' aria-label='Szukaj osoby lub numeru deklaracji' placeholder='Szukaj osoby lub numeru…' value='${esc(query)}'></div><select id='status-filter' class='compact' aria-label='Filtruj według statusu'><option value='all' ${filter==='all'?'selected':''}>Wszystkie statusy</option><option value='pending' ${filter==='pending'?'selected':''}>Oczekuje na TU</option><option value='accepted' ${filter==='accepted'?'selected':''}>Przyjęte</option><option value='rejected' ${filter==='rejected'?'selected':''}>Odrzucone</option></select></div></div><div id='table-body'>${tableBody()}</div></section>`;}
function tableBody(){const all=filteredRecords();tablePage=Math.min(tablePage,Math.max(0,Math.ceil(all.length/8)-1));const list=all.slice(tablePage*8,tablePage*8+8);return `<div class='table-scroll'><table><thead><tr><th>Osoba / identyfikator</th><th>Wariant</th><th>Składka</th><th>Wnioskowana od</th><th>Status deklaracji</th><th><span class='sr-only'>Szczegóły</span></th></tr></thead><tbody>${list.map(r=>`<tr><td><div class='person'><div class='avatar'>${esc(initials(r.name))}</div><div><strong>${esc(r.name)} ${r.personId==='ME'?`<span class='badge blue' style='padding:1px 5px;font-size:8px'>Twoje demo</span>`:''}</strong><small>${r.kind==='family'?'Członek rodziny · płatnik '+r.employeeId:r.employeeId} · ${r.id}</small></div></div></td><td>${plan(r.planId).name}</td><td><strong>${money(plan(r.planId).price)}</strong></td><td>${r.effective.split('-').reverse().join('.')}</td><td>${statusBadge(r)}</td><td><button class='btn sm ghost' data-record='${r.id}' aria-label='Szczegóły deklaracji ${r.id}'>${icon('chevron')}</button></td></tr>`).join('')||`<tr><td colspan='6' style='text-align:center;padding:35px'>Brak wyników dla wybranych kryteriów.</td></tr>`}</tbody></table></div><div class='table-foot'><span>${all.length?tablePage*8+1:0}–${Math.min(tablePage*8+8,all.length)} z ${all.length} deklaracji</span><div class='flex gap8'><button class='btn sm' data-action='table-prev' ${tablePage===0?'disabled':''} aria-label='Poprzednia strona'>${icon('left')}</button><span>Strona ${tablePage+1} / ${Math.max(1,Math.ceil(all.length/8))}</span><button class='btn sm' data-action='table-next' ${(tablePage+1)*8>=all.length?'disabled':''} aria-label='Następna strona'>${icon('arrow')}</button></div></div>`;}
function exportsView(){return `${heading('ROZLICZENIA','Eksporty gotowe do pobrania.','Przygotuj zestawienie za wybrany miesiąc i zachowaj historię plików.',periodSelect())}<div class='form-grid'><section class='card card-pad'><div class='quick-icon mb16'>${icon('download')}</div><h2>Lista płac</h2><p class='subtext mt16'>Kwoty pogrupowane według pracownika będącego płatnikiem. Rodzina doliczana dopiero po przyjęciu i od daty skuteczności.</p><p class='tiny mt16'>CSV z separatorem „;” i nagłówkiem UTF-8. Docelowy szablon importu wymaga uzgodnienia z systemem płacowym Klienta.</p><div class='mt24'>${btn('Pobierz CSV listy płac','export-payroll','primary','download')}</div></section><section class='card card-pad'><div class='quick-icon mb16'>${icon('upload')}</div><h2>Zestawienie dla TU</h2><p class='subtext mt16'>Lista deklaracji oczekujących na przyjęcie. Wygenerowanie pliku pozostawia ich status bez zmian.</p><p class='tiny mt16'>Format IBCP-TU-DEMO-v1. To nie jest uzgodniony format PZU ani integracja z ubezpieczycielem.</p><div class='mt24'>${btn('Pobierz CSV dla TU','export-tu','','download')}</div></section></div><section class='card card-pad mt24'><h2>Historia eksportów</h2>${state.exports.length?state.exports.map(e=>`<div class='doc-row'><div class='quick-icon'>${icon('doc')}</div><div><h3>${e.type==='payroll'?'Lista płac':'Zestawienie dla TU'} · ${e.period.slice(0,7)}</h3><p>${e.id} · ${e.count} ${e.type==='payroll'?'płatników':'deklaracji'} · ${new Date(e.created).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'})}</p></div><button class='btn sm' data-download-export='${e.id}'>${icon('download')}Pobierz ponownie</button></div>`).join(''):`<div class='empty'><p class='subtext'>Tutaj pojawią się przygotowane pliki. Każdy eksport zachowuje własny zapis danych.</p></div>`}</section>`;}
function doc(id){const contents={
 owu:`<div class='notice amber'>Makieta — brak zatwierdzonych OWU. Ten dokument nie opisuje rzeczywistej umowy PZU.</div><h3>Ogólne warunki ubezpieczenia</h3><p>W wersji produkcyjnej tutaj znajdzie się oryginalny plik otrzymany od TU: z numerem wersji, datą obowiązywania i powiązaniem z programem.</p><h3>Co będzie dostępne</h3><ul><li>Zakres ochrony i definicje zdarzeń.</li><li>Wyłączenia, ograniczenia i karencje.</li><li>Zasady przystąpienia, zmian oraz zakończenia ochrony.</li><li>Wymagane dokumenty i zgłaszanie świadczeń.</li></ul><p>Nie wygenerowano zastępczych OWU ani domniemanych warunków ubezpieczyciela.</p>`,
 product:`<div class='notice amber'>Makieta — wszystkie świadczenia i kwoty są fikcyjne, wyłącznie do pokazania interfejsu.</div><h3>Warianty demonstracyjne</h3><div class='table-scroll'><table><thead><tr><th>Wariant</th><th>Składka / mies.</th><th>Świadczenie — życie</th></tr></thead><tbody>${PLANS.map(p=>`<tr><td>${p.name}</td><td>${money(p.price)}</td><td>${money(p.life)}</td></tr>`).join('')}</tbody></table></div><h3>Płatność</h3><p>Scenariusz demo: potrącenie z wynagrodzenia, pracownik jako płatnik również za przyjętych członków rodziny. Właściwe zasady, zgody i termin potrącenia należy uzgodnić dla programu.</p><h3>Planowany początek</h3><p>1 grudnia 2026 r., po potwierdzeniu przyjęcia. Daty są elementem demonstracji.</p>`,
 broker:`<div class='notice amber'>Makieta informacji — treść prawna wymaga uzupełnienia i zatwierdzenia przed pilotem.</div><h3>Broker programu</h3><p>BCP Polska, Katowice. Docelowo: pełne dane podmiotu, informacje wymagane dla dystrybucji ubezpieczeń, dane kontaktowe oraz tryb reklamacji.</p><h3>Dane osobowe</h3><p>W tym demonstratorze dane pozostają w pamięci przeglądarki. Używaj wyłącznie fikcyjnych danych. Nie wpisuj prawdziwego numeru PESEL ani danych o zdrowiu.</p><p>W docelowym programie zostaną wskazani administratorzy danych i podmioty przetwarzające, cele i podstawy przetwarzania, odbiorcy, okresy retencji, prawa osób oraz kanał kontaktu. Podział ról BCP, pracodawcy i TU pozostaje do ustalenia.</p>`,
 continuation:`<div class='notice amber'>Informacja demonstracyjna — nie potwierdza prawa do kontynuacji ani jej warunków.</div><h3>Kończysz pracę w Auto Demo?</h3><p>Przed zakończeniem uczestnictwa sprawdź możliwość kontynuacji indywidualnej. Dostępność, termin zgłoszenia, składka i zakres wymagają potwierdzenia z TU dla konkretnego programu.</p><p>Docelowo aplikacja pokaże właściwe terminy, kontakt i link do ścieżki TU. W tej wersji nie składamy rzeczywistego wniosku.</p>`};modal(id==='owu'?'Ogólne warunki — makieta':id==='product'?'Karta produktu — demo':id==='broker'?'Broker i dane osobowe':'Kontynuacja ubezpieczenia',`<div class='doc-preview'>${contents[id]||''}</div><div class='form-actions'>${btn('Zamknij','close','primary')}</div>`);}
function declarationPreview(){const r=employeeRecord(state);if(!r)return;modal('Deklaracja '+r.id,`<div class='notice amber mb16'>Deklaracja demonstracyjna. Nie zawiera akceptacji TU i nie stanowi rzeczywistego przystąpienia.</div><div class='detail-list'><div class='detail-item'><span>Ubezpieczony</span><strong>${esc(r.name)}</strong></div><div class='detail-item'><span>E-mail demo</span><strong>${esc(r.email)}</strong></div><div class='detail-item'><span>Program / wersja</span><strong>Auto Demo / ${r.version}</strong></div><div class='detail-item'><span>Wariant przy przystąpieniu</span><strong>${plan(r.planId).name} · ${money(plan(r.planId).price)}</strong></div><div class='detail-item'><span>Wnioskowana data</span><strong>${date(r.effective)}</strong></div><div class='detail-item'><span>Płatnik</span><strong>${esc(r.name)}</strong></div><div class='detail-item'><span>Status</span>${statusBadge(r)}</div></div><div class='divider'></div><h3>Uposażeni w deklaracji</h3>${r.beneficiaries.map(b=>`<p class='subtext mt16'>${esc(b.name)} · ${b.share}%</p>`).join('')}<p class='tiny mt24'>Zapis oświadczeń i wariantu z chwili złożenia. Zmiany są oddzielnymi zdarzeniami.</p><div class='form-actions'>${btn('Zamknij','close','ghost')}${btn('Pobierz deklarację demo','download-declaration','primary','download')}</div>`);}
function recordModal(id){const r=state.records.find(r=>r.id===id&&r.tenant===TENANT);if(!r)return;modal('Deklaracja '+r.id,`<div class='flex mb16'><div class='avatar'>${esc(initials(r.name))}</div><div><h3>${esc(r.name)}</h3><p class='tiny'>${r.employeeId} · ${r.kind==='family'?'Członek rodziny':'Pracownik'}</p></div></div><div class='detail-list'><div class='detail-item'><span>Wariant</span><strong>${plan(r.planId).name} · ${money(plan(r.planId).price)}</strong></div><div class='detail-item'><span>Data wnioskowana</span><strong>${date(r.effective)}</strong></div><div class='detail-item'><span>Status</span>${statusBadge(r)}</div><div class='detail-item'><span>Płatnik</span><strong>${esc(state.records.find(x=>x.personId===r.payerId)?.name||r.name)}</strong></div></div><div class='notice mt24'>${icon('lock')}<span>Podgląd kadr nie ujawnia PESEL, uposażonych ani danych medycznych.</span></div>${r.status==='pending'?`<div class='divider'></div><h3>Symulator odpowiedzi TU</h3><p class='tiny mt16'>Przyciski służą wyłącznie demonstracji. Kadry nie zatwierdzają ochrony ubezpieczeniowej.</p><div class='form-field mt16'><label for='reject-reason'>Powód przy odrzuceniu</label><select id='reject-reason'><option>Niekompletne dane — przykład demo</option>Brak uprawnienia do programu — przykład demo</option>Wymagana korekta deklaracji — przykład demo</option></select></div><div class='form-actions'><button class='btn danger' data-reject-record='${r.id}'>Odrzuć · symulacja</button><button class='btn primary' data-accept-record='${r.id}'>${icon('check')}Przyjmij · symulacja</button></div>`:`<div class='notice ${r.status==='rejected'?'amber':'green'} mt24'>${icon('info')}<span>${esc(r.confirmation?.reason||'Dane początkowe demonstratora')} ${r.confirmation?`· ${esc(r.confirmation.id)}`:''}</span></div><div class='form-actions'>${btn('Zamknij','close','primary')}</div>`}`);}
function changeModal(cancel=false){const r=employeeRecord(state);if(!r||r.status!=='accepted'){toast('Najpierw zasymuluj przyjęcie deklaracji przez TU w panelu kadr.');return;}modal(cancel?'Zgłoś rezygnację':'Zmień wariant',`<p class='subtext mb16'>${cancel?'Rezygnacja będzie oczekiwać na potwierdzenie TU.':'Wybierz wariant. Zmiana będzie oczekiwać na potwierdzenie TU.'}</p><form id='change-form' data-type='${cancel?'cancel':'variant'}'>${!cancel?`<div class='form-field'><label for='new-plan'>Nowy wariant</label><select id='new-plan' name='plan'>${PLANS.filter(p=>p.id!==r.planId).map(p=>`<option value='${p.id}'>${p.name} — ${money(p.price)}/mies.</option>`).join('')}</select></div>`:''}<div class='notice amber mt24'>${icon('calendar')}<span>Wnioskowana data: ${date(EFFECTIVE)}. To reguła demonstracyjna, nie zatwierdzony warunek TU.${cancel?' W tym scenariuszu zakończenie ochrony pracownika kończy również powiązaną ochronę rodziny.':''}</span></div><div class='form-actions'>${btn('Anuluj','close','ghost')}<button type='submit' class='btn ${cancel?'danger':'primary'}'>${cancel?'Zgłoś rezygnację demo':'Zapisz zmianę demo'}</button></div></form>`);bindForms();}
function captureDraft(){if(!$('#declaration-form'))return;state.beneficiaries=state.beneficiaries.map((b,i)=>({name:$('#ben-'+i)?.value||b.name,share:Number($('#share-'+i)?.value??b.share)}));for(const k of ['documents','payroll','statement'])state.consents[k]=$(`#declaration-form [name='${k}']`)?.checked||false;save();}
function download(content,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportFile(type){const e=makeExport(state,type,period);save();download(e.content,`iBCP-demo-${type}-${period.slice(0,7)}-${e.id}.csv`);if(role==='hr')render();toast('Pobrano '+e.count+' '+(type==='payroll'?'pozycji listy płac.':'deklaracji. Ich status nie zmienił się.'));}
function bindForms(){
 $('#code-form')?.addEventListener('submit',e=>{e.preventDefault();if($('#company-code').value.trim().toUpperCase()!=='AUTO200'){error('Nie rozpoznano kodu. W demo użyj AUTO200.');return;}state.step=1;save();render();});
 $('#register-form')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),email=fd.get('email').trim().toLowerCase();if(!/^[^\s@]+@example\.com$/.test(email)){error('Użyj fikcyjnego adresu w domenie example.com.');return;}state.profile={name:fd.get('first').trim()+' '+fd.get('last').trim(),email};verification=true;save();render();$('#otp')?.focus();});
 $('#verify-form')?.addEventListener('submit',e=>{e.preventDefault();if($('#otp').value!=='246810'){error('Nieprawidłowy kod demo. Wpisz 246810.');return;}state.verified=true;verification=false;state.step=3;save();render();});
 $('#declaration-form')?.addEventListener('submit',e=>{e.preventDefault();captureDraft();try{submitDeclaration(state);save();render();window.scrollTo({top:0,behavior:'smooth'});}catch(e){error(e.message);}});
 $('#invite-form')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),email=fd.get('email').trim().toLowerCase();if(!/^[^\s@]+@example\.com$/.test(email)){error('Użyj fikcyjnego adresu w domenie example.com.');return;}if(state.invites.some(i=>i.email===email)||email===state.profile.email){error('Ten adres jest już użyty. Podaj inny adres demo.');return;}const inv={id:'FAM-'+crypto.randomUUID().slice(0,8),name:fd.get('name').trim(),email,relation:fd.get('relation'),status:'prepared',planId:'plus',created:TODAY};state.invites.push(inv);event(state,'Przygotowanie zaproszenia',inv.id,'Link demo. Wiadomość nie została wysłana.');save();close();page='family';render();modal('Zaproszenie demo jest gotowe',`<div class='success-icon'>${icon('mail')}</div><p class='subtext'>${esc(inv.name)} · ${esc(inv.email)}</p><p class='subtext mt16'>Wiadomość nie została wysłana. Otwórz ścieżkę bliskiej osoby, aby przetestować przystąpienie na osobnym koncie.</p><div class='notice mt24'>${icon('info')}<span>Link działa wyłącznie w tej przeglądarce z zapisanym stanem demonstratora.</span></div><div class='form-actions'><button class='btn' data-copy-invite='${inv.id}'>${icon('copy')}Kopiuj link demo</button><button class='btn primary' data-family='${inv.id}'>Otwórz ścieżkę ${icon('arrow')}</button></div>`);});
 $('#family-join-form')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);if(fd.get('otp')!=='246810'){error('Nieprawidłowy kod. Użyj 246810.');return;}const inv=state.invites.find(i=>i.id===familyId);inv.planId=fd.get('plan');try{submitDeclaration(state,{familyInviteId:inv.id});save();render();}catch(e){error(e.message);}});
 $('#change-form')?.addEventListener('submit',e=>{e.preventDefault();try{requestChange(state,e.target.dataset.type,new FormData(e.target).get('plan'));save();close();page='program';render();toast('Zmiana zapisana. Oczekuje na potwierdzenie TU.');}catch(e){error(e.message);}});
 $('#table-search')?.addEventListener('input',e=>{query=e.target.value;tablePage=0;$('#table-body').innerHTML=tableBody();});
 $('#status-filter')?.addEventListener('change',e=>{filter=e.target.value;tablePage=0;$('#table-body').innerHTML=tableBody();});
 $('#period')?.addEventListener('change',e=>{period=e.target.value;render();});
}
document.addEventListener('click',async e=>{
 const el=e.target.closest('button,a');if(!el)return;
 try{
 if(el.dataset.page){e.preventDefault();captureDraft();page=el.dataset.page;familyId=null;render();window.scrollTo(0,0);return;}
 if(el.dataset.role){captureDraft();role=el.dataset.role;page=role==='hr'?'overview':employeeRecord(state)?'program':'join';familyId=null;render();window.scrollTo(0,0);return;}
 if(el.dataset.plan){state.selectedPlan=el.dataset.plan;save();render();return;}
 if(el.dataset.removeBeneficiary){captureDraft();state.beneficiaries.splice(Number(el.dataset.removeBeneficiary),1);save();render();return;}
 if(el.dataset.family){close();familyId=el.dataset.family;role='employee';page='family';render();window.scrollTo(0,0);return;}
 if(el.dataset.copyInvite){const u=new URL(location.href);u.hash='invite='+el.dataset.copyInvite;try{await navigator.clipboard.writeText(u.href);toast('Link demonstracyjny skopiowany.');}catch{modal('Link demonstracyjny',`<div class='form-field'><label for='copy-link'>Skopiuj ten adres</label><input id='copy-link' readonly value='${esc(u.href)}'></div>`);}return;}
 if(el.dataset.record){recordModal(el.dataset.record);return;}
 if(el.dataset.acceptRecord||el.dataset.rejectRecord){confirm(state,el.dataset.acceptRecord||el.dataset.rejectRecord,!!el.dataset.acceptRecord,$('#reject-reason')?.value||'');save();close();render();toast('Odpowiedź TU zapisana w symulacji.');return;}
 if(el.dataset.confirmChange){confirmChange(state,el.dataset.confirmChange);save();render();toast('Zmiana przyjęta w symulacji.');return;}
 if(el.dataset.downloadExport){const exp=state.exports.find(x=>x.id===el.dataset.downloadExport);download(exp.content,`iBCP-demo-${exp.type}-${exp.id}.csv`);return;}
 const a=el.dataset.action;if(!a)return;e.preventDefault();
 if(a==='close'){close();return;}
 if(a==='menu'){$('.sidebar').classList.toggle('open');return;}
 if(a.startsWith('step-')){captureDraft();state.step=Number(a.slice(5));verification=false;if(state.step===4&&!state.verified)state.step=2;save();render();window.scrollTo(0,0);return;}
 if(a.startsWith('doc-')){captureDraft();doc(a.slice(4));return;}
 if(a.startsWith('go-')){page=a.slice(3);familyId=null;render();window.scrollTo(0,0);return;}
 if(a==='register-back'){verification=false;render();return;}
 if(a==='beneficiary-add'){captureDraft();state.beneficiaries.push({name:'Jan Demo',share:0});save();render();return;}
 if(a==='invite'){inviteModal();return;}
 if(a==='family-return'){familyId=null;page='family';window.history.replaceState(null,'',location.pathname);render();return;}
 if(a==='my-declaration'){declarationPreview();return;}
 if(a==='change'||a==='cancel'){changeModal(a==='cancel');return;}
 if(a==='export-payroll'||a==='export-tu'){exportFile(a==='export-payroll'?'payroll':'tu');return;}
 if(a==='table-prev'||a==='table-next'){tablePage+=a==='table-prev'?-1:1;$('#table-body').innerHTML=tableBody();return;}
 if(a==='download-declaration'){const {printBrand}=await import('./print-brand.mjs');const r=employeeRecord(state);const body=`<!doctype html><html lang='pl'><meta charset='utf-8'><title>Deklaracja demo ${r.id}</title>${printBrand}<h1>iBCP · Deklaracja ${r.id}</h1><p class='note'>DEMO — fikcyjne dane. Nie stanowi przystąpienia ani potwierdzenia ochrony.</p><table><tr><td>Ubezpieczony</td><td>${esc(r.name)}</td></tr><tr><td>E-mail demo</td><td>${esc(r.email)}</td></tr><tr><td>Program</td><td>Auto Demo · ${r.version}</td></tr><tr><td>Wariant</td><td>${plan(r.planId).name} · ${money(plan(r.planId).price)}</td></tr><tr><td>Wnioskowana data</td><td>${date(r.effective)}</td></tr><tr><td>Złożono</td><td>${esc(r.submittedAt)}</td></tr></table><h2>Uposażeni</h2>${r.beneficiaries.map(b=>`<p>${esc(b.name)} — ${b.share}%</p>`).join('')}<p>Potwierdzono dokumenty demonstracyjne, potrącenie składki w demo oraz fikcyjność danych. Deklaracja zapisana jako osobny dokument; decyzja TU jest oddzielnym zdarzeniem.</p></html>`;download(body,`iBCP-deklaracja-demo-${r.id}.html`,'text/html;charset=utf-8');toast('Pobrano deklarację demo do otwarcia lub wydruku.');return;}
 if(a==='reset'){modal('Zacząć demo od nowa?',`<p class='subtext'>Usuniemy tylko postęp tego demonstratora w tej przeglądarce. Początkowe fikcyjne dane Auto Demo zostaną odtworzone.</p><div class='form-actions'>${btn('Zostaw postęp','close','ghost')}${btn('Zresetuj demo','reset-confirm','danger','refresh')}</div>`);return;}
 if(a==='reset-confirm'){state=freshState();role='employee';page='join';verification=false;familyId=null;query='';filter='all';tablePage=0;save();close();window.history.replaceState(null,'',location.pathname);render();toast('Demo przywrócone do stanu początkowego.');return;}
 if(a==='mass-invite'){modal('Zaproszenia pracowników',`<p class='subtext mb16'>Przygotuj wiadomość demonstracyjną do dystrybucji z kodem firmy. Ten prototyp nie wysyła poczty.</p><div class='instructions' id='invite-copy'>Zapraszamy do demonstracyjnego programu iBCP dla Auto Demo sp. z o.o.<br>Kod firmy: AUTO200.<br>Wybierz wariant 60, 90 lub 120 zł i złóż deklarację testową. Korzystaj wyłącznie z fikcyjnych danych.</div><div class='form-actions'>${btn('Zamknij','close','ghost')}${btn('Kopiuj treść','copy-mass-invite','primary','copy')}</div>`);return;}
 if(a==='copy-mass-invite'){try{await navigator.clipboard.writeText($('#invite-copy').innerText);toast('Skopiowano treść demonstracyjną.');}catch{toast('Zaznacz i skopiuj treść wiadomości powyżej.');}return;}
 if(a==='help'){modal('Jak przetestować iBCP',`<div class='instructions'><strong>Ścieżka demonstracyjna</strong><ol><li>Wpisz kod firmy <strong>AUTO200</strong>.</li><li>Użyj fikcyjnych danych i adresu @example.com.</li><li>Wpisz kod weryfikacyjny <strong>246810</strong>.</li><li>Wybierz wariant, sprawdź dokumenty i złóż deklarację.</li><li>Zaproś bliską osobę i otwórz jej ścieżkę.</li><li>Przełącz widok na Kadry, znajdź deklarację i zasymuluj odpowiedź TU.</li><li>Pobierz CSV listy płac lub eksport demonstracyjny dla TU.</li></ol></div><div class='notice mt24'>${icon('info')}<span>Postęp zapisuje się lokalnie w tej przeglądarce. Konto, uprawnienia i odpowiedzi TU są symulowane. Nie używaj prawdziwych danych.</span></div><div class='form-actions'>${btn('Rozumiem','close','primary')}</div>`);return;}
 }catch(err){error(err.message);}
});
document.addEventListener('input',e=>{if(e.target.closest('#declaration-form'))captureDraft();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)close();}});
const initialHash=new URLSearchParams(location.hash.slice(1));if(initialHash.has('invite')){const id=initialHash.get('invite');if(state.invites.some(i=>i.id===id)){familyId=id;page='family';}}
render();
